package grc1155

import (
	"errors"

	"gno.land/p/nt/avl/v0"
)

// TokenID identifies one token type inside a Token. Ids accepted by write
// paths are restricted to [A-Za-z0-9_.-], so a stored id is always safe to
// render in markdown and safe to embed in the composite storage keys this
// package derives from it. A TokenID is only a string conversion — reads do
// not re-validate it, so consumers rendering a caller-supplied id must apply
// the same charset check themselves (URI does).
type TokenID string

func (t TokenID) String() string { return string(t) }

// A Teller is a capability that acts as some account whenever it writes.
// IsCanonicalTeller confirms a Teller was minted by this package — an embedding
// forgery fails the check — but it does NOT reveal which account the Teller acts
// as: a caller-scoped CallerTeller and the admin-grade ImpersonateTeller (which
// acts as an arbitrary address) are both canonical. So it is an authenticity
// check on the implementation, not an authorization guard on the acting account;
// a caller accepting a Teller from outside must still establish, out of band, what
// account that Teller is entitled to act as. And because the write methods take
// the caller's own cur/rlm as an argument, a consumer that accepts a Teller from
// outside must run IsCanonicalTeller BEFORE handing that rlm to it — a forged
// Teller receiving a live rlm could act as the consumer's realm.
// safeTransferFrom/safeBatchTransferFrom are omitted: EIP-1155's receiver check
// needs a registry, and aliasing it would imply false safety.
type Teller interface {
	GetName() string
	GetSymbol() string
	ID() string
	URI(tid TokenID) string
	TotalSupply(tid TokenID) int64
	BalanceOf(owner address, tid TokenID) (int64, error)
	BalanceOfBatch(owners []address, tids []TokenID) ([]int64, error)
	IsApprovedForAll(owner, operator address) bool

	SetApprovalForAll(_ int, rlm realm, operator address, approved bool) error
	TransferFrom(_ int, rlm realm, from, to address, tid TokenID, amount int64) error
	BatchTransferFrom(_ int, rlm realm, from, to address, tids []TokenID, amounts []int64) error
}

// Extension hooks fire on every mint/transfer/burn. This is a trust grant to the
// issuer, not an EIP-1155 feature: only the issuer can attach one (RegisterExtension
// holds the PrivateLedger), but once attached the hook runs arbitrary issuer code on
// every movement, a panic in OnMint/OnTransfer/OnBurn aborts the transaction before
// the movement is announced — an implicit veto over transfers — and gas scales
// linearly with the extension count. Hooks run after the ledger write so they observe
// the post-movement state; only a caller that recovers from the panic keeps that write.
// For batch operations the hooks fire once per batch entry, in batch order — and
// only after EVERY entry has been written, so entry 0's hook already observes the
// full batch applied, not a partially-applied one.
// Holders of a collection's tokens are therefore trusting the issuer not to freeze or
// tax movement through this surface. Hooks take no rlm params (they cannot capture cur);
// attach only via RegisterExtension.
type Extension interface {
	ExtensionKind() string // unique; duplicates rejected at register
	OnMint(to address, tid TokenID, amount int64)
	OnTransfer(from, to address, tid TokenID, amount int64)
	OnBurn(from address, tid TokenID, amount int64)
}

type ExtensionView interface {
	ExtensionKind() string
	TokenID() string // core Token.ID
}

type Token struct {
	id         string // raw creation pkgpath + "." + symbol
	name       string
	symbol     string
	defaultURI string
	ledger     *PrivateLedger
	// origRealm is the PkgPath of the realm that created the token, captured
	// unforgeably in NewToken. A frame-relative teller only works there.
	origRealm string
}

type PrivateLedger struct {
	token             *Token
	supplies          avl.Tree // TokenID -> int64 total supply; entry removed at zero
	balances          avl.Tree // "owner:tokenID" -> int64; entry removed at zero
	uris              avl.Tree // TokenID -> per-token URI override
	operatorApprovals avl.Tree // "owner:operator" -> bool
	extensions        []Extension
}

var (
	ErrInvalidTokenID             = errors.New("invalid token id")
	ErrInvalidAddress             = errors.New("invalid address")
	ErrCallerIsNotOwnerOrApproved = errors.New("caller is not token owner or approved")
	ErrApprovalToCurrentOwner     = errors.New("approval to current owner")
	ErrCannotTransferToSelf       = errors.New("cannot send transfer to self")
	ErrInsufficientBalance        = errors.New("insufficient balance")
	ErrInvalidAmount              = errors.New("invalid amount")
	ErrLengthMismatch             = errors.New("batch length mismatch")
	ErrEmptyBatch                 = errors.New("empty batch")
	ErrBatchTooLarge              = errors.New("batch too large")
	ErrInvalidURI                 = errors.New("invalid uri")
	ErrOverflow                   = errors.New("integer overflow")
	ErrReadonly                   = errors.New("teller is readonly")
	ErrSpoofedRealm               = errors.New("rlm does not match the current crossing frame")
	ErrForeignCallerTeller        = errors.New("frame-relative teller used outside the token's realm")
	ErrNotRealm                   = errors.New("rlm must be a realm (got EOA/origin)")
	ErrInvalidName                = errors.New("invalid token name (empty, too long, or contains control chars)")
	ErrInvalidSymbol              = errors.New("invalid token symbol (empty, too long, or contains chars outside [A-Za-z0-9_-])")
)

const (
	MaxTokenIDLen = 64
	MaxBatchSize  = 64
	MaxURILen     = 256
	// maxPageSize bounds HoldingsOf/TokenIDs page reads.
	maxPageSize = 50
)

// Symbol charset matches grc20reg slug (embedded in Token.ID / events).
const (
	MaxNameLen   = 64
	MaxSymbolLen = 11
)

const (
	// NewToken announces every token creation; see NewToken for why it is a
	// complete provenance signal.
	NewTokenEvent = "NewToken"
	// Mint and burn emit TransferSingle/TransferBatch with an empty from/to
	// address respectively (EIP-1155). Their "operator" attribute is empty —
	// the ledger has no spender for those ops; transfers carry the spender.
	TransferSingleEvent = "TransferSingle"
	TransferBatchEvent  = "TransferBatch"
	ApprovalForAllEvent = "ApprovalForAll"
	URIEvent            = "URI"
)

var zeroAddress = address("")

type fnTeller struct {
	accountFn func(_ int, rlm realm) address
	// homeGuard marks a frame-relative teller, whose writes are confined to
	// the token's own realm. See fnTeller.guardHome.
	homeGuard bool
	*Token
}

var _ Teller = (*fnTeller)(nil)

// IsCanonicalTeller reports whether t was minted by this package, rejecting Tellers
// forged by embedding *fnTeller in a wrapper. It does NOT discriminate by capability
// grade: CallerTeller, ReadonlyTeller, RealmTeller, RealmSubTeller and the admin-grade
// ImpersonateTeller all return true. Do not treat a true result as proof that a Teller
// is a caller-scoped capability — establish the acting account separately.
func IsCanonicalTeller(t Teller) bool {
	_, ok := t.(*fnTeller)
	return ok
}

package counter

import "strconv"

var counter int

func Increment(_ realm) int {
	counter++
	return counter
}

func Render(_ string) string {
	return strconv.Itoa(counter)
}

// Package tavernboard implements TavernBoard: an on-chain quest board
// where posters escrow testnet GNOT bounties, agents or humans claim
// quests, submit proof of work, and get paid on confirmation — building
// a public, on-chain reputation score along the way.
//
// Deployed (Onyx testnet) at:
// gno.land/r/g1wcgeganvf6zkpyt8j2tx3h7p3f8afn0my8pw0k/tavernboard/v1
package tavernboard

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
)

// QuestStatus is the lifecycle state of a quest.
type QuestStatus int

const (
	StatusOpen QuestStatus = iota
	StatusClaimed
	StatusSubmitted
	StatusCompleted
	StatusCancelled
)

func (s QuestStatus) String() string {
	switch s {
	case StatusOpen:
		return "OPEN"
	case StatusClaimed:
		return "CLAIMED"
	case StatusSubmitted:
		return "SUBMITTED"
	case StatusCompleted:
		return "COMPLETED"
	case StatusCancelled:
		return "CANCELLED"
	}
	return "UNKNOWN"
}

// Quest is a single bounty posting held in escrow by this realm.
type Quest struct {
	ID          uint64
	Poster      address
	Title       string
	Description string
	Bounty      int64 // in ugnot, escrowed in the realm account
	Deadline    int64 // block height; a claimed quest can be cancelled by the poster after this height
	Status      QuestStatus
	Claimer     address
	ProofURL    string
	ProofHash   string // hash of the proof payload, as supplied by the claimer
}

var (
	quests     = map[uint64]*Quest{}
	questCount uint64
	reputation = map[address]int64{} // completed quests per address
)

// PostQuest creates a new quest. The bounty is whatever ugnot the caller
// attaches to the call (gnokey -send), escrowed in the realm account until
// the quest is completed (paid to the claimer) or cancelled (refunded).
// deadlineBlocks is relative to the current block height.
// Returns the new quest ID.
func PostQuest(cur realm, title string, description string, deadlineBlocks int64) uint64 {
	poster := requireUser(cur, "PostQuest")
	if title == "" {
		panic("PostQuest: title is required")
	}
	if deadlineBlocks <= 0 {
		panic("PostQuest: deadlineBlocks must be > 0")
	}
	bounty := unsafe.OriginSend().AmountOf("ugnot")
	if bounty <= 0 {
		panic("PostQuest: attach a bounty in ugnot (gnokey maketx call -send <amount>ugnot)")
	}
	return createQuest(poster, title, description, bounty, deadlineBlocks)
}

// createQuest stores a quest whose bounty is already in the realm account.
// It is separate from PostQuest so unit tests can seed quests without an
// on-chain send envelope.
func createQuest(poster address, title string, description string, bounty int64, deadlineBlocks int64) uint64 {
	questCount++
	q := &Quest{
		ID:          questCount,
		Poster:      poster,
		Title:       title,
		Description: description,
		Bounty:      bounty,
		Deadline:    runtime.ChainHeight() + deadlineBlocks,
		Status:      StatusOpen,
	}
	quests[q.ID] = q
	return q.ID
}

// ClaimQuest assigns an OPEN quest to the caller.
func ClaimQuest(cur realm, id uint64) {
	claimer := requireUser(cur, "ClaimQuest")
	q := mustQuest(id, "ClaimQuest")
	if q.Status != StatusOpen {
		panic("ClaimQuest: quest is not open")
	}
	if claimer == q.Poster {
		panic("ClaimQuest: poster cannot claim their own quest")
	}
	q.Claimer = claimer
	q.Status = StatusClaimed
}

// SubmitProof records proof of work for a CLAIMED quest. Only the claimer
// may submit. proofHash is an off-chain content hash supplied by the
// claimer so the poster can verify the proof payload at proofURL.
func SubmitProof(cur realm, id uint64, proofURL string, proofHash string) {
	claimer := requireUser(cur, "SubmitProof")
	q := mustQuest(id, "SubmitProof")
	if q.Status != StatusClaimed {
		panic("SubmitProof: quest is not in claimed state")
	}
	if claimer != q.Claimer {
		panic("SubmitProof: only the claimer can submit proof")
	}
	if proofURL == "" {
		panic("SubmitProof: proofURL is required")
	}
	q.ProofURL = proofURL
	q.ProofHash = proofHash
	q.Status = StatusSubmitted
}

// ConfirmComplete is called by the poster once the submitted proof checks
// out. The escrowed bounty is paid to the claimer and the claimer's
// on-chain reputation increases by 1.
func ConfirmComplete(cur realm, id uint64) {
	poster := requireUser(cur, "ConfirmComplete")
	q := mustQuest(id, "ConfirmComplete")
	if q.Status != StatusSubmitted {
		panic("ConfirmComplete: quest has no submitted proof to confirm")
	}
	if poster != q.Poster {
		panic("ConfirmComplete: only the poster can confirm completion")
	}
	pay(cur, q.Claimer, q.Bounty)
	q.Status = StatusCompleted
	reputation[q.Claimer]++
}

// CancelQuest refunds the escrowed bounty to the poster. Allowed while the
// quest is OPEN, or once a CLAIMED quest is past its deadline. A quest with
// submitted proof cannot be cancelled — the poster must confirm it or wait
// for a future dispute flow.
func CancelQuest(cur realm, id uint64) {
	poster := requireUser(cur, "CancelQuest")
	q := mustQuest(id, "CancelQuest")
	if poster != q.Poster {
		panic("CancelQuest: only the poster can cancel")
	}
	switch {
	case q.Status == StatusOpen:
		// always refundable
	case q.Status == StatusClaimed && runtime.ChainHeight() > q.Deadline:
		// claimer missed the deadline
	default:
		panic("CancelQuest: quest cannot be cancelled in its current state")
	}
	pay(cur, q.Poster, q.Bounty)
	q.Status = StatusCancelled
}

// QuestCount returns how many quests have ever been posted.
func QuestCount() uint64 {
	return questCount
}

// ReputationOf returns the number of quests an address has completed.
func ReputationOf(addr address) int64 {
	return reputation[addr]
}

// GetQuest returns a one-line summary of a quest, for clients and agents.
func GetQuest(id uint64) string {
	q, ok := quests[id]
	if !ok {
		return "quest not found"
	}
	return "#" + u64(q.ID) +
		" [" + q.Status.String() + "] " + q.Title +
		" | bounty: " + i64(q.Bounty) + "ugnot" +
		" | poster: " + q.Poster.String() +
		" | claimer: " + addrOrDash(q.Claimer) +
		" | deadline block: " + i64(q.Deadline)
}

// Render draws the quest board for gnoweb. With no path it lists every
// quest; with path "quest/<id>" it shows one quest in detail.
func Render(path string) string {
	if strings.HasPrefix(path, "quest/") {
		idStr := strings.TrimPrefix(path, "quest/")
		id, err := strconv.ParseUint(idStr, 10, 64)
		if err != nil {
			return "# TavernBoard\n\nInvalid quest id: " + idStr
		}
		return renderQuest(id)
	}
	return renderBoard()
}

func renderBoard() string {
	var b strings.Builder
	b.WriteString("# TavernBoard — on-chain quest board for AI agents & humans\n\n")
	b.WriteString("Post a quest with an escrowed GNOT bounty, let an agent or a human claim it, verify the proof, and release the bounty. Every completion builds on-chain reputation.\n\n")
	if questCount == 0 {
		b.WriteString("No quests yet. Be the first to post one.\n")
		return b.String()
	}
	b.WriteString("## Quests\n\n")
	for id := uint64(1); id <= questCount; id++ {
		q := quests[id]
		b.WriteString("- " + GetQuest(id) + " — [details](quest/" + u64(q.ID) + ")\n")
	}
	b.WriteString("\nTotal quests posted: " + u64(questCount) + "\n")
	return b.String()
}

func renderQuest(id uint64) string {
	q, ok := quests[id]
	if !ok {
		return "# TavernBoard\n\nQuest not found."
	}
	var b strings.Builder
	b.WriteString("# Quest #" + u64(q.ID) + ": " + q.Title + "\n\n")
	b.WriteString(q.Description + "\n\n")
	b.WriteString("- Status: " + q.Status.String() + "\n")
	b.WriteString("- Bounty: " + i64(q.Bounty) + " ugnot (escrowed in this realm)\n")
	b.WriteString("- Poster: " + q.Poster.String() + "\n")
	b.WriteString("- Claimer: " + addrOrDash(q.Claimer) + "\n")
	b.WriteString("- Deadline block: " + i64(q.Deadline) + "\n")
	if q.ProofURL != "" {
		b.WriteString("- Proof URL: " + q.ProofURL + "\n")
		b.WriteString("- Proof hash: " + q.ProofHash + "\n")
	}
	b.WriteString("\n[← back to the board]()\n")
	return b.String()
}

// --- helpers ---

// requireUser enforces that the realm function was invoked directly by an
// externally owned account (not cross-realm), and returns that account.
func requireUser(cur realm, fn string) address {
	if !cur.Previous().IsUserCall() {
		panic(fn + ": must be called directly by a user or agent account")
	}
	return cur.Previous().Address()
}

func mustQuest(id uint64, fn string) *Quest {
	q, ok := quests[id]
	if !ok {
		panic(fn + ": quest not found")
	}
	return q
}

// pay sends ugnot out of the realm's escrow account.
func pay(cur realm, to address, amount int64) {
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), to, chain.Coins{chain.NewCoin("ugnot", amount)})
}

func addrOrDash(a address) string {
	if a == "" {
		return "-"
	}
	return a.String()
}

func u64(v uint64) string { return strconv.FormatUint(v, 10) }
func i64(v int64) string  { return strconv.FormatInt(v, 10) }

package tavernboard

import (
	"chain"
	"strings"
	"testing"
)

// Project testnet accounts (see testnet-account.txt in the project vault;
// addresses are public and safe to embed).
var (
	posterAddr = address("g1wcgeganvf6zkpyt8j2tx3h7p3f8afn0my8pw0k")
	agentAddr  = address("g1n9u4cn09v7mdzsusu7k75c6yxnscxdkrcas26u")
	pkgAddr    = chain.PackageAddress("gno.land/r/g1wcgeganvf6zkpyt8j2tx3h7p3f8afn0my8pw0k/tavernboard/v1")
)

func setupEscrow() {
	// Fund the realm account so escrow payouts/refunds can be made.
	testing.IssueCoins(pkgAddr, chain.Coins{{Denom: "ugnot", Amount: 100000000}})
	testing.SetHeight(1000)
}


// assertAborts runs f and fails the test unless f aborts (a panic crossing
// the realm boundary) with a message containing substr. It uses the revive
// builtin, the same mechanism as gno.land/p/nt/uassert — reimplemented here
// so the test suite needs no external package downloads.
func assertAborts(cur realm, t *testing.T, substr string, f func()) {
	t.Helper()
	r := revive(f)
	if r == nil {
		t.Fatalf("expected abort containing %q, but the call succeeded", substr)
	}
	msg, ok := r.(string)
	if !ok {
		t.Fatalf("expected abort containing %q, got non-string abort: %v", substr, r)
	}
	if !strings.Contains(msg, substr) {
		t.Fatalf("expected abort containing %q, got %q", substr, msg)
	}
}

// Full happy path: post -> claim -> submit -> confirm, escrow paid out,
// reputation credited.
func TestFullFlow(cur realm, t *testing.T) {
	setupEscrow()

	// Poster posts a quest with a 5 GNOT bounty attached.
	testing.SetRealm(testing.NewUserRealm(posterAddr))
	testing.SetOriginSend(chain.Coins{{Denom: "ugnot", Amount: 5000000}})
	id := PostQuest(cross(cur), "Write a tavern ballad", "Compose a short song about the Gnome Tavern.", 100)
	if id == 0 {
		t.Fatalf("expected non-zero quest id")
	}
	if got := QuestCount(); got != id {
		t.Fatalf("QuestCount = %d, want %d", got, id)
	}
	q := quests[id]
	if q.Status != StatusOpen || q.Bounty != 5000000 || q.Poster != posterAddr {
		t.Fatalf("unexpected quest after post: %+v", q)
	}
	if q.Deadline != 1100 {
		t.Fatalf("deadline = %d, want 1100", q.Deadline)
	}

	// Poster cannot claim their own quest.
	assertAborts(cur, t, "poster cannot claim their own quest", func() { ClaimQuest(cross(cur), id) })

	// Agent claims it.
	testing.SetRealm(testing.NewUserRealm(agentAddr))
	ClaimQuest(cross(cur), id)
	if q.Status != StatusClaimed || q.Claimer != agentAddr {
		t.Fatalf("unexpected quest after claim: %+v", q)
	}

	// Poster cannot submit proof; only the claimer can.
	testing.SetRealm(testing.NewUserRealm(posterAddr))
	assertAborts(cur, t, "only the claimer can submit proof", func() {
		SubmitProof(cross(cur), id, "https://example.com/ballad", "abc123")
	})

	// Claimer submits proof.
	testing.SetRealm(testing.NewUserRealm(agentAddr))
	SubmitProof(cross(cur), id, "https://example.com/ballad", "abc123")
	if q.Status != StatusSubmitted || q.ProofURL != "https://example.com/ballad" || q.ProofHash != "abc123" {
		t.Fatalf("unexpected quest after submit: %+v", q)
	}

	// Claimer cannot confirm their own work.
	assertAborts(cur, t, "only the poster can confirm", func() { ConfirmComplete(cross(cur), id) })

	// Poster confirms -> completed + reputation.
	testing.SetRealm(testing.NewUserRealm(posterAddr))
	ConfirmComplete(cross(cur), id)
	if q.Status != StatusCompleted {
		t.Fatalf("status = %v, want COMPLETED", q.Status)
	}
	if rep := ReputationOf(agentAddr); rep != 1 {
		t.Fatalf("agent reputation = %d, want 1", rep)
	}

	// Render output mentions the quest.
	if out := Render(""); !strings.Contains(out, "Write a tavern ballad") {
		t.Fatalf("board render missing quest title:\n%s", out)
	}
	if out := Render("quest/" + u64(id)); !strings.Contains(out, "COMPLETED") {
		t.Fatalf("quest render missing status:\n%s", out)
	}
	if s := GetQuest(id); !strings.Contains(s, "COMPLETED") {
		t.Fatalf("GetQuest = %q", s)
	}
}

// A quest with no attached bounty must be rejected.
func TestPostQuestRequiresBounty(cur realm, t *testing.T) {
	setupEscrow()
	testing.SetRealm(testing.NewUserRealm(posterAddr))
	testing.SetOriginSend(chain.Coins{})
	assertAborts(cur, t, "attach a bounty", func() {
		PostQuest(cross(cur), "Free labour", "No bounty attached.", 10)
	})
}

// Cancelling an OPEN quest refunds the poster and closes the quest.
func TestCancelOpen(cur realm, t *testing.T) {
	setupEscrow()
	testing.SetRealm(testing.NewUserRealm(posterAddr))
	id := createQuest(posterAddr, "Deliver a keg", "Bring one keg to the tavern cellar.", 2000000, 50)

	// A stranger cannot cancel it.
	testing.SetRealm(testing.NewUserRealm(agentAddr))
	assertAborts(cur, t, "only the poster can cancel", func() { CancelQuest(cross(cur), id) })

	testing.SetRealm(testing.NewUserRealm(posterAddr))
	CancelQuest(cross(cur), id)
	if quests[id].Status != StatusCancelled {
		t.Fatalf("status = %v, want CANCELLED", quests[id].Status)
	}
}

// A CLAIMED quest can only be cancelled after its deadline has passed.
func TestCancelClaimedAfterDeadline(cur realm, t *testing.T) {
	setupEscrow()
	testing.SetRealm(testing.NewUserRealm(posterAddr))
	id := createQuest(posterAddr, "Polish the mugs", "Every mug in the tavern, shining.", 1000000, 10)

	testing.SetRealm(testing.NewUserRealm(agentAddr))
	ClaimQuest(cross(cur), id)

	// Before the deadline the poster cannot cancel.
	testing.SetRealm(testing.NewUserRealm(posterAddr))
	assertAborts(cur, t, "cannot be cancelled", func() { CancelQuest(cross(cur), id) })

	// After the deadline the refund path opens.
	testing.SetHeight(2000)
	CancelQuest(cross(cur), id)
	if quests[id].Status != StatusCancelled {
		t.Fatalf("status = %v, want CANCELLED", quests[id].Status)
	}
}

// Unknown quest IDs are rejected everywhere.
func TestUnknownQuest(cur realm, t *testing.T) {
	setupEscrow()
	testing.SetRealm(testing.NewUserRealm(posterAddr))
	assertAborts(cur, t, "quest not found", func() { ClaimQuest(cross(cur), 999999) })
	if s := GetQuest(999999); s != "quest not found" {
		t.Fatalf("GetQuest(unknown) = %q", s)
	}
}

package slotswitch_smoke

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"time"
)

type checkIn struct {
	height int64
	at     int64
}

var checkIns = make(map[address]checkIn)
var total int

// CheckIn records one test action per signer.
func CheckIn(cur realm) {
	runtime.AssertOriginCall()
	if !cur.Previous().IsUserCall() || len(unsafe.OriginSend()) != 0 {
		panic("use a direct wallet call with no attached funds")
	}
	caller := cur.Previous().Address()
	if _, exists := checkIns[caller]; exists {
		return
	}
	checkIns[caller] = checkIn{height: runtime.ChainHeight(), at: time.Now().Unix()}
	total++
}

func Total() int {
	return total
}

func SignedAt(signer address) int64 {
	return checkIns[signer].height
}

func SignedTime(signer address) int64 {
	return checkIns[signer].at
}

func Render(path string) string {
	return "# SlotSwitch testnet smoke test\n\n" +
		"Confirmed wallet check-ins: **" + strconv.Itoa(total) + "**.\n\n" +
		"Use the Actions tab to call CheckIn with an Onyx test wallet."
}

// Agent Guestbook — a daily check-in and guestbook realm for gno.land.
//
// A port of the Agent Guestbook concept (first deployed on BNB Smart Chain
// for the Binance Agent ID Hackathon) to Gno: any gno.land account can check
// in once per UTC day, build a consecutive-day streak, and leave a short
// public message in the guestbook. There is no owner and no admin: nobody
// can edit or delete another account's check-ins, and the realm holds no
// funds and issues no token.
package agentguestbook

import (
	"chain"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
)

// RealmPath is the path this realm is deployed at; used in Render output.
const RealmPath = "gno.land/r/g1928v64a9lvvmd4w0yausatmxdu0sq5vl6k8vu6/agentguestbook"

// MaxMessageLength is the maximum guestbook message length, in bytes.
const MaxMessageLength = 280

// recentLimit caps how many recent check-ins are kept for the Render page.
const recentLimit = 10

// AgentStats holds one account's check-in statistics and guestbook entry.
type AgentStats struct {
	LastCheckInDay int64 // UTC day number (unix seconds / 86400) of the last counted check-in; 0 = never
	CurrentStreak  int64 // consecutive-day streak ending at LastCheckInDay
	BestStreak     int64 // longest streak ever reached
	TotalCheckIns  int64 // total counted check-ins by this account
	Message        string // latest guestbook message
}

var (
	agents        = avl.NewTree() // address string -> *AgentStats
	totalCheckIns int64
	uniqueAgents  int64
	recent        []string // most recent checking-in addresses, newest first
)

// currentDay returns today's UTC day number from the chain clock.
func currentDay() int64 {
	return time.Now().Unix() / 86400
}

// nextStreak computes the streak after a counted check-in today, given the
// day of the previous counted check-in and the streak that ended then.
func nextStreak(lastDay, today, current int64) int64 {
	if lastDay == today-1 {
		return current + 1
	}
	return 1
}

// validateMessage enforces the guestbook message size limit.
func validateMessage(message string) {
	if len(message) > MaxMessageLength {
		panic("guestbook: message too long (max 280 bytes)")
	}
}

// CheckIn counts today's check-in for the caller and stores the guestbook
// message. A repeat call on the same UTC day only updates the message; a
// day is never counted twice. Panics if the message exceeds 280 bytes.
func CheckIn(cur realm, message string) string {
	validateMessage(message)

	addr := cur.Previous().Address()
	key := addr.String()
	today := currentDay()

	stats, exists := getStats(key)
	if exists && stats.LastCheckInDay == today {
		// Same-day repeat: guestbook update only, no double counting.
		stats.Message = message
		chain.Emit("MessageUpdated", "agent", key, "day", strconv.FormatInt(today, 10))
		return "Already checked in today — guestbook message updated."
	}

	if !exists {
		stats = &AgentStats{}
		uniqueAgents++
	}

	stats.CurrentStreak = nextStreak(stats.LastCheckInDay, today, stats.CurrentStreak)
	if stats.CurrentStreak > stats.BestStreak {
		stats.BestStreak = stats.CurrentStreak
	}
	stats.LastCheckInDay = today
	stats.TotalCheckIns++
	stats.Message = message
	agents.Set(key, stats)

	totalCheckIns++
	pushRecent(key)

	chain.Emit("CheckedIn",
		"agent", key,
		"day", strconv.FormatInt(today, 10),
		"streak", strconv.FormatInt(stats.CurrentStreak, 10),
	)
	return "Checked in. Streak: " + strconv.FormatInt(stats.CurrentStreak, 10) +
		" day(s), total check-ins: " + strconv.FormatInt(stats.TotalCheckIns, 10) + "."
}

// GetAgent returns a human-readable summary of one account's guestbook
// record, or a note that the account has never checked in.
func GetAgent(addr address) string {
	stats, exists := getStats(addr.String())
	if !exists {
		return addr.String() + " has not checked in yet."
	}
	return addr.String() +
		" — streak " + strconv.FormatInt(stats.CurrentStreak, 10) +
		" (best " + strconv.FormatInt(stats.BestStreak, 10) + ")" +
		", total check-ins " + strconv.FormatInt(stats.TotalCheckIns, 10) +
		", last message: " + stats.Message
}

// GetStats returns the realm-wide counters.
func GetStats() string {
	return "total check-ins: " + strconv.FormatInt(totalCheckIns, 10) +
		", unique agents: " + strconv.FormatInt(uniqueAgents, 10)
}

func getStats(key string) (*AgentStats, bool) {
	v := agents.Get(key)
	if v == nil {
		return nil, false
	}
	return v.(*AgentStats), true
}

func pushRecent(key string) {
	// Remove an earlier occurrence so the list holds distinct addresses.
	for i, k := range recent {
		if k == key {
			recent = append(recent[:i], recent[i+1:]...)
			break
		}
	}
	recent = append([]string{key}, recent...)
	if len(recent) > recentLimit {
		recent = recent[:recentLimit]
	}
}

// sanitizeInline neutralizes markdown-significant characters in
// user-supplied text before it is written into Render output.
func sanitizeInline(s string) string {
	r := strings.NewReplacer(
		"\n", " ",
		"\r", " ",
		"`", "'",
		"<", "(",
		">", ")",
		"[", "(",
		"]", ")",
		"#", "",
		"*", "",
		"_", "",
		"|", "/",
	)
	return r.Replace(s)
}

// Render is the realm's gnoweb page: live counters, the latest guestbook
// entries, and how to check in.
func Render(_ string) string {
	var b strings.Builder
	b.WriteString("# Agent Guestbook\n\n")
	b.WriteString("A daily check-in and guestbook on gno.land. Check in once per UTC day, ")
	b.WriteString("keep your streak alive, and leave a message for the next visitor.\n\n")
	b.WriteString("**Total check-ins:** " + strconv.FormatInt(totalCheckIns, 10) +
		" · **Unique agents:** " + strconv.FormatInt(uniqueAgents, 10) + "\n\n")

	b.WriteString("## Latest entries\n\n")
	if len(recent) == 0 {
		b.WriteString("No check-ins yet — be the first.\n\n")
	}
	for _, key := range recent {
		stats, ok := getStats(key)
		if !ok {
			continue
		}
		b.WriteString("- **" + key + "** — streak " +
			strconv.FormatInt(stats.CurrentStreak, 10) +
			", " + strconv.FormatInt(stats.TotalCheckIns, 10) + " check-in(s)")
		if stats.Message != "" {
			b.WriteString(": “" + sanitizeInline(stats.Message) + "”")
		}
		b.WriteString("\n")
	}

	b.WriteString("\n## Check in\n\n")
	b.WriteString("From your own gno.land account, call the realm's `CheckIn` function with your message (max 280 bytes):\n\n")
	b.WriteString("```\ngnokey maketx call \\\n")
	b.WriteString("  -pkgpath \"" + RealmPath + "\" \\\n")
	b.WriteString("  -func \"CheckIn\" \\\n")
	b.WriteString("  -args \"your guestbook message\" \\\n")
	b.WriteString("  -gas-fee 1000000ugnot -gas-wanted 2000000 \\\n")
	b.WriteString("  -broadcast -chainid onyx-1 \\\n")
	b.WriteString("  -remote \"https://rpc.onyx.testnets.gno.land:443\" \\\n")
	b.WriteString("  <your-key-name>\n```\n\n")
	b.WriteString("No owner, no admin, no funds held, no token — an activity record only.\n")
	return b.String()
}

// Package fees is the entry-fee rate each account pays on Mimir's pool and VS
// markets (the gno.land port of contracts/MimirFees.sol).
//
// Everyone pays BaseBps (0.5%) of what they put in. A lower rate needs a fee
// ticket signed by the signer: "this account is tier T until `expires`". The
// account submits it with ApplyTicket, normally in the same transaction as its
// stake. Mimir's server signs no tickets.
//
// Signatures are ed25519 over TicketMessage(account, tier, expires), which
// binds the chain id and this realm's path, so a ticket cannot be replayed on
// another network or another deployment.
//
// Trust: the signer can only lower an account's rate (BaseBps is the most
// anyone pays), so a stolen signer key costs the protocol revenue, never a user
// money. The owner revokes it at once (RevokeSigner); a new signer waits
// SignerTimelock, so a stolen owner key cannot install one quietly. Both retire
// every ticket the old signer issued (each ticket carries the signer epoch it
// was applied under).
package fees

import (
	"chain"
	"chain/runtime"
	"crypto/ed25519"
	"encoding/hex"
	"strconv"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Deployer is the initial owner, the address that deploys these realms.
const Deployer = address("g12dcsmwccgdxasqde2eumua88tlrkw83kqf6tcz")

const (
	BaseBps   = int64(50) // 0.5%
	HolderBps = int64(25) // 0.25%: tier 1 ticket
	WhaleBps  = int64(10) // 0.1%: tier 2 ticket

	// A ticket may not outlive this, so a discount ends within two days.
	MaxTicketSeconds         = int64(2 * 24 * 60 * 60)
	OwnershipTimelockSeconds = int64(2 * 24 * 60 * 60)
	SignerTimelockSeconds    = int64(2 * 24 * 60 * 60)
)

type Ticket struct {
	Tier    int
	Expires int64
	Epoch   int64
}

var (
	tickets avl.Tree // address -> *Ticket

	signer          []byte // ed25519 public key; nil when revoked or unset
	owner           address
	pendingOwner    address
	pendingOwnerEta int64
	// Bumped on every signer change or revoke: tickets applied under an earlier epoch pay BaseBps.
	signerEpoch      int64
	pendingSigner    []byte
	pendingSignerEta int64
	signerEverSet    bool
	selfPath         string
)

func init(cur realm) {
	owner = Deployer
	selfPath = cur.PkgPath()
	chain.Emit("OwnershipTransferred", "previous", "", "next", owner.String())
}

func now() int64 { return time.Now().Unix() }

func assertOwner(cur realm) {
	if cur.Previous().Address() != owner {
		panic("NotOwner")
	}
}

func decodeKey(pubHex string) []byte {
	k, err := hex.DecodeString(pubHex)
	if err != nil || len(k) != 32 {
		panic("BadSignerKey")
	}
	return k
}

// SetInitialSigner installs the first signer, once, as the Solidity
// constructor did. Every later change goes through the timelock.
func SetInitialSigner(cur realm, pubHex string) {
	assertOwner(cur)
	if signerEverSet {
		panic("SignerAlreadySet")
	}
	signer = decodeKey(pubHex)
	signerEverSet = true
	chain.Emit("SignerChanged", "previous", "", "next", pubHex)
}

// RevokeSigner is the emergency stop: no ticket verifies any more, and the
// ones applied stop counting.
func RevokeSigner(cur realm) {
	assertOwner(cur)
	chain.Emit("SignerChanged", "previous", hex.EncodeToString(signer), "next", "")
	signer = nil
	signerEverSet = true
	signerEpoch++
}

func QueueSigner(cur realm, pubHex string) {
	assertOwner(cur)
	pendingSigner = decodeKey(pubHex)
	pendingSignerEta = now() + SignerTimelockSeconds
	chain.Emit("SignerQueued", "next", pubHex, "eta", strconv.FormatInt(pendingSignerEta, 10))
}

// ExecuteSigner is permissionless once due, like the market realms' queued changes.
func ExecuteSigner(cur realm) {
	if pendingSignerEta == 0 {
		panic("NothingQueued")
	}
	if now() < pendingSignerEta {
		panic("Timelocked")
	}
	chain.Emit("SignerChanged", "previous", hex.EncodeToString(signer), "next", hex.EncodeToString(pendingSigner))
	signer = pendingSigner
	signerEverSet = true
	signerEpoch++
	pendingSigner = nil
	pendingSignerEta = 0
}

func TransferOwnership(cur realm, next address) {
	assertOwner(cur)
	if !next.IsValid() {
		panic("ZeroAddress")
	}
	pendingOwner = next
	pendingOwnerEta = now() + OwnershipTimelockSeconds
	chain.Emit("OwnershipTransferStarted", "previous", owner.String(), "next", next.String(),
		"eta", strconv.FormatInt(pendingOwnerEta, 10))
}

func CancelOwnershipTransfer(cur realm) {
	assertOwner(cur)
	if pendingOwner == "" {
		panic("NotPendingOwner")
	}
	chain.Emit("OwnershipTransferCancelled", "pending", pendingOwner.String())
	pendingOwner = ""
	pendingOwnerEta = 0
}

func AcceptOwnership(cur realm) {
	caller := cur.Previous().Address()
	if pendingOwner == "" || caller != pendingOwner {
		panic("NotPendingOwner")
	}
	if now() < pendingOwnerEta {
		panic("Timelocked")
	}
	chain.Emit("OwnershipTransferred", "previous", owner.String(), "next", caller.String())
	owner = caller
	pendingOwner = ""
	pendingOwnerEta = 0
}

// TicketMessage is the exact byte string the signer signs for (account, tier, expires).
func TicketMessage(account address, tier int, expires int64) string {
	return ufmt.Sprintf("Mimir Fees v1|%s|%s|%s|%d|%d",
		runtime.ChainID(), selfPath, account.String(), tier, expires)
}

// ApplyTicket stores a signed tier for the caller: a ticket is bound to the
// account it was signed for.
func ApplyTicket(cur realm, tier int, expires int64, sigHex string) {
	account := cur.Previous().Address()
	if tier < 0 || tier > 2 {
		panic("BadTier")
	}
	if expires <= now() || expires > now()+MaxTicketSeconds {
		panic("BadExpiry")
	}
	sig, err := hex.DecodeString(sigHex)
	if err != nil || len(sig) != 64 || signer == nil {
		panic("BadSignature")
	}
	if !ed25519.Verify(signer, []byte(TicketMessage(account, tier, expires)), sig) {
		panic("BadSignature")
	}
	tickets.Set(account.String(), &Ticket{Tier: tier, Expires: expires, Epoch: signerEpoch})
	chain.Emit("TicketApplied", "account", account.String(), "tier", strconv.Itoa(tier),
		"expires", strconv.FormatInt(expires, 10))
}

// EntryBps is the account's entry fee in basis points right now.
func EntryBps(account address) int64 {
	v := tickets.Get(account.String())
	if v == nil {
		return BaseBps
	}
	t := v.(*Ticket)
	if t.Expires <= now() || t.Epoch != signerEpoch {
		return BaseBps
	}
	switch t.Tier {
	case 2:
		return WhaleBps
	case 1:
		return HolderBps
	}
	return BaseBps
}

func Owner() address        { return owner }
func PendingOwner() address { return pendingOwner }
func SignerEpoch() int64    { return signerEpoch }
func Signer() string        { return hex.EncodeToString(signer) }

func Render(path string) string {
	if path != "" {
		return ufmt.Sprintf("Entry fee for %s: %d bps\n", path, EntryBps(address(path)))
	}
	return ufmt.Sprintf("# Mimir fees\n\nBase entry fee: %d bps (0.5%%). Tier 1: %d bps. Tier 2: %d bps.\n\n"+
		"Owner: %s\n\nSigner epoch: %d\n\nLook up an account: `:<address>`\n",
		BaseBps, HolderBps, WhaleBps, owner.String(), signerEpoch)
}

